require_once dirname(dirname(__DIR__)).'/src/bootstrap.php';$user=Auth::requireRole('hospital');$hospital=current_hospital($user);$hid=(int)$hospital['id'];$counts=[];$q=db()->prepare("SELECT COUNT(*) total,SUM(status='open') open_count,SUM(status='fulfilled') fulfilled_count,SUM(status='expired') expired_count FROM emergency_requests WHERE hospital_id=?");$q->execute([$hid]);$counts=$q->fetch()?:[];$a=db()->prepare("SELECT COUNT(*) FROM emergency_invites i JOIN emergency_requests e ON e.id=i.emergency_id WHERE e.hospital_id=? AND i.status='accepted'");$a->execute([$hid]);$accepted=(int)$a->fetchColumn();$t=db()->prepare("SELECT COUNT(*) total,SUM(status='completed') completed FROM blood_transfer_requests WHERE from_hospital_id=? OR to_hospital_id=?");$t->execute([$hid,$hid]);$transfers=$t->fetch()?:[];$c=db()->prepare("SELECT COUNT(*) total FROM donation_campaigns WHERE hospital_id=?");$c->execute([$hid]);$campaigns=(int)$c->fetchColumn();$recent=db()->prepare("SELECT e.id,e.blood_group,e.urgency,e.district,e.status,e.created_at,(SELECT COUNT(*) FROM emergency_invites i WHERE i.emergency_id=e.id AND i.status='accepted') accepted FROM emergency_requests e WHERE e.hospital_id=? ORDER BY e.created_at DESC LIMIT 30");$recent->execute([$hid]);$rows=$recent->fetchAll();$pageTitle='Hospital Reports';require dirname(dirname(__DIR__)).'/src/templates/header.php';?>
<section class="dashboard"><div class="container"><div class="dash-head"><div><div class="eyebrow">Hospital operations</div><h1>Reports</h1><p class="page-note">Simple operational summaries for the academic prototype.</p></div><a class="btn btn-outline" href="<?=e(url('hospital/export.php?type=requests'))?>">Export Requests CSV</a></div><?=hospital_nav($user)?><div class="metrics"><div class="metric"><span>Total requests</span><strong><?=e((string)($counts['total']??0))?></strong></div><div class="metric"><span>Fulfilled</span><strong><?=e((string)($counts['fulfilled_count']??0))?></strong></div><div class="metric"><span>Accepted donor responses</span><strong><?=e((string)$accepted)?></strong></div><div class="metric"><span>Campaigns</span><strong><?=e((string)$campaigns)?></strong></div></div><div class="grid-2"><div class="card"><h3>Request status</h3><ul class="summary-list"><li>Open: <strong><?=e((string)($counts['open_count']??0))?></strong></li><li>Expired: <strong><?=e((string)($counts['expired_count']??0))?></strong></li><li>Fulfilled: <strong><?=e((string)($counts['fulfilled_count']??0))?></strong></li></ul></div><div class="card"><h3>Transfer activity</h3><ul class="summary-list"><li>Total transfer records: <strong><?=e((string)($transfers['total']??0))?></strong></li><li>Completed transfers: <strong><?=e((string)($transfers['completed']??0))?></strong></li></ul><p><a href="<?=e(url('hospital/export.php?type=transfers'))?>">Export transfer CSV →</a></p></div></div><h2 class="mt-2">Recent requests</h2><div class="table-wrap"><table class="table"><thead><tr><th>ID</th><th>Blood</th><th>Urgency</th><th>District</th><th>Accepted</th><th>Status</th><th>Created</th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td>#<?=e((string)$r['id'])?></td><td><?=e($r['blood_group'])?></td><td><?=e($r['urgency'])?></td><td><?=e($r['district'])?></td><td><?=e((string)$r['accepted'])?></td><td><?=e($r['status'])?></td><td><?=e($r['created_at'])?></td></tr><?php endforeach;?></tbody></table></div></div></section>
